    g.checkpoint(V32(0, hwY - 12 + 0.1, 686), 0);
    g.mover(new Vector3(4.4, 1, 4.4), (t) => V32(lerp2(0, 14, t), hwY - 11 + Math.sin(t * 3.14) * 2, lerp2(706, 726, t)), 5.5);
    g.mover(new Vector3(4.4, 1, 4.4), (t) => V32(lerp2(0, -12, t), hwY - 10, lerp2(720, 742, t)), 6.2, 0.5);
