    g.enemy("gnat", V32(10, hwY - 8, 730));
    tower(-17, 820, 22, 18, hwY - 10);
    g.panel(V32(-17, hwY - 10 + 0.1, 826), 0, 46);
    const cx = 0, cz = 886, R = 17, turns = 2, yTop = hwY - 10, yBot = 12;
    const pts = [];
    const N = 64;
    for (let i = 0; i <= N; i++) {
      const u = i / N;
      const a = 1.5 * Math.PI + u * turns * 2 * Math.PI;
      pts.push(V32(cx + Math.sin(a) * R, lerp2(yTop, yBot, u), cz + Math.cos(a) * R));
    }
    g.channel(pts, 3.4, 7.5, M.stone, Math.PI * 0.06, Math.PI * 0.94);
    kit.cyl(6, 10, 84, { x: cx, y: 0, z: cz }, M.building, 16);
    g.prism(V32(cx - R - 4, (yTop + yBot) / 2 + 4, cz));
