      if (this.gfx.composer) {
        for (const p of this.gfx.composer.passes) if (p.scene !== void 0) p.scene = this.scene;
      }
      this.world.clear();
      this.killY = -100;
      this.fogColor = 8947848;
      this.orbs = new OrbField(this.scene);
      this.enemies = new Enemies(this.scene, this);
      this.fx = new Fx(this.scene);
