        this.deaths = 0;
        this.cores = 0;
        this.prismsGot = 0;
        this.chipsGot = 0;
        this.comboN = 0;
        this.stylePts = 0;
        this.player.boostMeter = 50;
        this.player.orbs = 0;
        this.audioTrack(meta.music);
        this.cam.snapBehind(this.player);
